from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
UNIT_KG = {"kg": Decimal("1"), "g": Decimal("0.001"), "lb": Decimal("0.45392"), "oz": Decimal("0.02837")}
MONTHS = {m: i + 1 for i, m in enumerate("jan feb mar apr may jun jul aug sep oct nov dec".split())}
COLUMNS = {"id", "type", "shipped", "gross", "net", "status", "note", "rec", "ref", "date",
           "weight", "state", "kind", "booked", "gross_kg", "net_kg", "t", "typ"}
DELIMS = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
FW = {
    "FW1": dict(length=42, type=(9, 10), id=(0, 9), shipped=(10, 17), weight=(17, 25), status=(25, 26),
                dateform="YYYYDDD", factor=Decimal("0.001")),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27),
                dateform="YYYYMMDD", factor=Decimal("0.01")),
    "FW3": dict(length=41, type=(16, 17), id=(0, 9), shipped=(9, 16), weight=(17, 24), status=(24, 25),
                dateform="YYYYDDD", factor=Decimal("0.1") * UNIT_KG["lb"]),
}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}
HARBOR_STATUS = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled", "RET": "returned", "HLD": "held"}


def read_bytes(path):
    with open(path, "rb") as handle:
        data = handle.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", errors="replace")
    if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return data[2:].decode("utf-16-le" if data[:2] == b"\xff\xfe" else "utf-16-be", errors="replace")
    encoding = "utf-8"
    head = data[:1000].decode("latin-1")
    found = re.search(r"(?m)^#\s*charset\s*:\s*([^\s]+)", head)
    if found:
        try:
            codecs.lookup(found.group(1))
            encoding = found.group(1)
        except LookupError:
            pass
    return data.decode(encoding, errors="replace")


def split_lines(text):
    lines = text.split("\n")
    return [line[:-1] if line.endswith("\r") else line for line in lines]


def parse_id(text):
    found = re.match(r"(?i)^\s*SH[^0-9]*(\d+)\s*$", text or "")
    return int(found.group(1)) if found else None


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", (text or "").strip().lower())


def norm_type(text):
    text = (text or "").strip().lower()
    if text.startswith("v"):
        return "void"
    if text.startswith(("c", "a")):
        return "correction"
    return "new"


def parse_date(text, form):
    text = (text or "").strip()
    form = (form or "iso").strip().lower()
    found = re.match(r"^(\d{4})-(\d{2})-(\d{2})(?:$|[T ])", text)
    if found and "T" in text.upper():
        value = datetime.fromisoformat(text.replace(" ", "T").replace("z", "Z"))
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc).date()
    if found:
        return date(int(found.group(1)), int(found.group(2)), int(found.group(3)))
    found = re.match(r"^(\d{1,2}) ([A-Za-z]{3})[A-Za-z]* (\d{4})$", text)
    if found:
        return date(int(found.group(3)), MONTHS[found.group(2).lower()], int(found.group(1)))
    if form == "serial" or re.fullmatch(r"\d+(\.\d+)?", text) and form not in ("yyyymmdd", "yyyyddd"):
        return date(1899, 12, 30) + timedelta(days=int(float(text)))
    if form == "yyyymmdd":
        return date(int(text[:4]), int(text[4:6]), int(text[6:8]))
    if form == "yyyyddd":
        return date(int(text[:4]), 1, 1) + timedelta(days=int(text[4:7]) - 1)
    parts = re.split(r"[-/.]", text)
    a, b, c = (int(part) for part in parts)
    if form in ("iso", "ymd"):
        return date(a, b, c)
    if form in ("dmy", "dd-mm-yyyy", "dd.mm.yyyy", "dd/mm/yyyy"):
        return date(c, b, a)
    if form in ("mm/dd/yyyy", "mdy"):
        return date(c, a, b)
    raise ValueError("date form " + form)


def parse_number(text, decimal_comma):
    text = text.strip()
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Decimal(text)


def weight_kg(value, unit, decimal_comma):
    found = re.match(r"^\s*([-+0-9.,]+)\s*([A-Za-z]*)\s*$", value)
    number, own = found.group(1), found.group(2).lower()
    if own in UNIT_KG:
        unit = own
    return parse_number(number, decimal_comma) * UNIT_KG[unit]


def month_of(day):
    return "%04d-%02d" % (day.year, day.month)


def make(num, kind, status, kg, day):
    return {"num": num, "type": kind, "status": status, "kg": kg, "month": month_of(day) if day else None}


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    quoting = delim == ","
    seq = None
    directives = {}
    header = None
    records = []
    lines = split_lines(text)
    index = 0
    while index < len(lines):
        line = lines[index]
        index += 1
        if not line.strip():
            continue
        if line.startswith("#"):
            found = re.match(r"^#\s*([^:]+?)\s*:\s*(.*?)\s*$", line)
            if found:
                name = found.group(1).lower()
                directives[name] = found.group(2)
                if name == "seq" and seq is None:
                    try:
                        seq = int(found.group(2))
                    except ValueError:
                        pass
            else:
                found = re.match(r"^#\s*\w+\s+seq=(\d+)", line)
                if found and seq is None:
                    seq = int(found.group(1))
            continue
        if quoting:
            while line.count('"') % 2 and index < len(lines):
                line += "\n" + lines[index]
                index += 1
            row = next(csv.reader([line]))
        else:
            row = line.split(delim)
        names = [field.strip().lower() for field in row]
        if all(name in COLUMNS for name in names) and any(names):
            header = names
            continue
        if header is None:
            continue
        rec = parse_row(depot, header, row, directives)
        if rec:
            records.append(rec)
    return seq, records


def parse_row(depot, header, row, directives):
    unit = "kg"
    decimal_comma = depot == "west"
    for key in ("weight unit", "unit"):
        if key in directives:
            value = directives[key].lower()
            first = re.match(r"\s*([a-z]+)", value)
            if first and first.group(1) in UNIT_KG:
                unit = first.group(1)
            if "decimal comma" in value:
                decimal_comma = True
    form = directives.get("dates", directives.get("date format"))
    if depot == "west" and form is None:
        form = "DD.MM.YYYY"
    if depot == "river" and form is None:
        form = "MM/DD/YYYY"
    weight_index = None
    for position, name in enumerate(header):
        if name in ("gross", "weight") or name.startswith(("gross_", "weight_")):
            weight_index = position
            break
    row = list(row)
    row_unit = None
    if weight_index is not None and len(row) == len(header) + 1 and row[weight_index + 1].strip().lower() in UNIT_KG:
        row_unit = row[weight_index + 1].strip().lower()
        del row[weight_index + 1]
    row = row + [""] * (len(header) - len(row))
    data = dict(zip(header, row))
    idtext = data.get("id", data.get("ref", ""))
    num = parse_id(idtext)
    if num is None:
        return None
    kind = norm_type(data.get("type", data.get("rec", data.get("kind", data.get("typ", data.get("t", ""))))))
    if kind == "void":
        return make(num, kind, None, None, None)
    name = header[weight_index]
    if "_" in name and name.rsplit("_", 1)[1] in UNIT_KG:
        unit = name.rsplit("_", 1)[1]
    elif row_unit:
        unit = row_unit
    kg = weight_kg(row[weight_index], unit, decimal_comma)
    day = parse_date(data.get("shipped", data.get("date", "")), form)
    status = data.get("status", data.get("state", ""))
    if depot == "harbor":
        status = HARBOR_STATUS.get(status.strip().upper(), status)
    return make(num, kind, norm_status(status), kg, day)


def parse_north(text):
    seq = None
    records = []
    for line in split_lines(text):
        if not line.strip():
            continue
        value = json.loads(line)
        for item in value if isinstance(value, list) else [value]:
            if not isinstance(item, dict):
                continue
            if "meta" in item:
                if seq is None:
                    seq = item["meta"].get("seq")
                continue
            num = parse_id(str(item.get("id", "")))
            if num is None:
                continue
            kind = norm_type(item.get("kind", ""))
            if kind == "void":
                records.append(make(num, kind, None, None, None))
                continue
            kg = None
            for key, value in item.items():
                if key.startswith("weight_") and key.rsplit("_", 1)[1] in UNIT_KG:
                    kg = Decimal(str(value)) * UNIT_KG[key.rsplit("_", 1)[1]]
            day = parse_date(item["shipped_at"], "iso")
            records.append(make(num, kind, norm_status(item.get("status")), kg, day))
    return seq, records


def parse_central(data):
    root = ET.fromstring(data)
    seq = root.get("seq")
    seq = int(seq) if seq else None
    root_unit = (root.get("weight-unit") or "kg").lower()
    records = []
    for element in root.iter("shipment"):
        num = parse_id(element.get("id"))
        if num is None:
            continue
        kind = norm_type(element.get("type", ""))
        if kind == "void":
            records.append(make(num, kind, None, None, None))
            continue
        weight = element.find("weight")
        unit = (weight.get("unit") or element.get("weight-unit") or root_unit).lower()
        kg = parse_number(weight.text, False) * UNIT_KG[unit]
        shipped = element.get("shipped")
        if shipped is None:
            shipped = element.findtext("shipped")
        day = parse_date(shipped, "iso")
        records.append(make(num, kind, norm_status(element.findtext("status")), kg, day))
    return seq, records


def parse_south(text):
    seq = None
    layout = None
    records = []
    for line in split_lines(text):
        if line.startswith("#SEQ"):
            seq = int(line.split()[1])
            continue
        if line.startswith("#LAYOUT"):
            layout = line.split()[1]
            continue
        if line.startswith("#") or line.startswith("\x0c") or not line.strip():
            continue
        by_length = [name for name, spec in FW.items() if spec["length"] == len(line)]
        if by_length:
            name = by_length[0]
        elif layout in FW:
            name = layout
            line = line.ljust(FW[name]["length"])
        else:
            continue
        spec = FW[name]
        cut = lambda key: line[spec[key][0]:spec[key][1]]
        num = parse_id(cut("id"))
        if num is None:
            continue
        kind = norm_type(cut("type"))
        if kind == "void":
            records.append(make(num, kind, None, None, None))
            continue
        kg = Decimal(cut("weight").strip()) * spec["factor"]
        day = parse_date(cut("shipped"), spec["dateform"])
        records.append(make(num, kind, FW_STATUS.get(cut("status").strip(), cut("status")), kg, day))
    return seq, records


def parse_file(depot, path):
    data = read_bytes(path)
    if depot == "central":
        return parse_central(data)
    text = decode(data)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        seq, records = parse_file(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))
    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        store = current[depot] = {}
        for seq, name, records in sorted(files, key=lambda item: (item[0], item[1])):
            for rec in records:
                if rec["type"] == "new":
                    if rec["num"] in store:
                        resends += 1
                    else:
                        store[rec["num"]] = rec
                elif rec["type"] == "correction":
                    corrections += 1
                    store[rec["num"]] = rec
                else:
                    corrections += 1
                    store.pop(rec["num"], None)
    rank = {name: i for i, name in enumerate(ORDER)}
    owners = {}
    for depot in sorted(current, key=lambda name: rank.get(name, len(rank))):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)
    depot_totals = {depot: [0, Decimal(0)] for depot in sorted(exports)}
    month_totals = {}
    for num, depots in owners.items():
        rec = current[depots[0]][num]
        if rec["status"] not in ("delivered", "delivered_late"):
            continue
        depot_totals[depots[0]][0] += 1
        depot_totals[depots[0]][1] += rec["kg"]
        entry = month_totals.setdefault(rec["month"], [0, Decimal(0)])
        entry[0] += 1
        entry[1] += rec["kg"]

    def fmt(entry):
        return {"shipments": entry[0], "total_kg": float(entry[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}

    result = {
        "depots": {name: fmt(entry) for name, entry in depot_totals.items()},
        "months": {name: fmt(month_totals[name]) for name in sorted(month_totals)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)


